const pino = require("pino");

/**
 * next-logger loads this to build the Pino instance used for Next.js internal + patched console logs.
 * Keeps JSON output and aligns level with {@link LOG_LEVEL} / app logger.
 */
const logger = (defaultConfig) =>
  pino({
    ...defaultConfig,
    level: process.env.LOG_LEVEL ?? defaultConfig.level ?? "info",
  });

module.exports = { logger };

