const prismaBin = resolve(process.cwd(), "node_modules/.bin/prisma");
const result = spawnSync(prismaBin, process.argv.slice(2), {
  stdio: "inherit",
  env: process.env,
});

if (result.signal) process.kill(process.pid, result.signal);
process.exit(result.status ?? 1);

